 breakpoint\n$breakpoint-mobile: 1024px;\n\n//messages list max width\n$messages-list-max-width: 800px;\n\n//message max width\n$message-max-width: 680px;\n\n//message utils width\n$message-utils-width: 100px;\n\n//message form max height\n$message-form-max-height: 180px;\n\n$color-call-background: rgba(34, 34, 34, 0.8);\n$color-guests-avatar: #ffffff;\n$color-background-guests-avatar: #b9b9b9;\n\n\n//chat font size\n$chat-font-size: 15px;\n\n//chat line height\n$chat-line-height: 1.6em;\n\n// fade transition\n$fade-transition: all var(--animation-quick, 100ms) ease-in-out;\n$fade-transition-slow: all var(--animation-slow, 300ms) ease-in-out;\n\n.fade {\n\t&-enter {\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t}\n}\n\n.slide-down {\n\t&-enter {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t\t/* force top container to resize during animation */\n\t\tposition: absolute !important;\n\t}\n}\n","\n@import '../../assets/variables';\n\n.wrapper {\n\tdisplay: flex;\n\tjustify-content: center;\n\tpadding: 12px 0;\n\tmin-height: 69px;\n}\n\n.new-message {\n\twidth: 100%;\n\tdisplay: flex;\n\tjustify-content: center;\n\t&-form {\n\t\talign-items: flex-end;\n\t\tdisplay: flex;\n\t\tposition:relative;\n\t\tflex: 0 1 700px;\n\t\tmargin: 0 4px;\n\t\t&__emoji-picker {\n\t\t\tposition: absolute;\n\t\t\tbottom: 1px;\n\t\t\tz-index: 1;\n\t\t}\n\n\t\t&__input {\n\t\t\tflex-grow: 1;\n\t\t\toverflow: hidden;\n\t\t\tposition: relative;\n\t\t}\n\n\t\t// Override NcRichContenteditable styles\n\t\t& &__richContenteditable {\n\t\t\tborder: 1px solid var(--color-border-dark);\n\t\t\tborder-radius: calc(var(--default-clickable-area) / 2);\n\t\t\tpadding: 8px 16px 8px 44px;\n\t\t\tmax-height: 180px;\n\t\t\t&:hover,\n\t\t\t&:focus,\n\t\t\t&:active {\n\t\t\t\tborder: 1px solid var(--color-primary-element);\n\t\t\t}\n\t\t}\n\n\t\t&__quote {\n\t\t\tmargin: 0 16px 12px 24px;\n\t\t\tbackground-color: var(--color-background-hover);\n\t\t\tpadding: 8px;\n\t\t\tborder-radius: var(--border-radius-large);\n\t\t}\n\n\t\t// put a grey round background when popover is opened\n\t\t// or hover-focused\n\t\t&__icon:hover,\n\t\t&__icon:focus,\n\t\t&__icon:active {\n\t\t\topacity: $opacity_full;\n\t\t\t// good looking on dark AND white bg\n\t\t\tbackground-color: $icon-focus-bg;\n\t\t}\n\n\t}\n}\n\n// Override actions styles TODO: upstream this change\n// Targeting two classess for specificity\n:deep(.action-item__menutoggle.action-item__menutoggle--with-icon-slot) {\n\topacity: 1 !important;\n\t&:hover,\n\t&:focus {\n\t\tbackground-color: var(--color-background-hover) !important;\n\t}\n\t&:disabled {\n\t\topacity: .5 !important;\n\t}\n}\n\n.new-text-file {\n\tdisplay: flex;\n\tjustify-content: center;\n\talign-items: center;\n\tflex-direction: column;\n\tgap: 28px;\n\tpadding: 20px;\n\n\t&__buttons {\n\t\tdisplay: flex;\n\t\tgap: 4px;\n\t\tjustify-content: center;\n\t\tmargin-top: 20px;\n\t}\n\n\t&__form {\n\t\twidth: 100%;\n\n\t\t.templates-picker__list {\n\t\t\tmargin-top: 20px;\n\t\t\tdisplay: grid;\n\t\t\tgrid-gap: calc(var(--margin) * 2);\n\t\t\tgrid-auto-columns: 1fr;\n\t\t\t// We want maximum 5 columns. Putting 6 as we don't count the grid gap. So it will always be lower than 6\n\t\t\tmax-width: calc(var(--fullwidth) * 6);\n\t\t\tgrid-template-columns: repeat(auto-fit, var(--fullwidth));\n\t\t\t// Make sure all rows are the same height\n\t\t\tgrid-auto-rows: 1fr;\n\t\t\t// Center the columns set\n\t\t\tjustify-content: center;\n\t\t}\n\t}\n}\n"],"sourceRoot":""}]);
