fade-transition: all var(--animation-quick, 100ms) ease-in-out;\n$fade-transition-slow: all var(--animation-slow, 300ms) ease-in-out;\n\n.fade {\n\t&-enter {\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t}\n}\n\n.slide-down {\n\t&-enter {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t\t/* force top container to resize during animation */\n\t\tposition: absolute !important;\n\t}\n}\n","\n@import '../assets/variables';\n\n$clickable-area: 44px;\n$margin: 8px;\n\n.placeholder-main {\n\tmax-width: $messages-list-max-width;\n\tposition: relative;\n\tmargin: auto;\n\tpadding: 0;\n}\n\n.placeholder-list {\n\tposition: absolute;\n\ttranslate: translateZ(0);\n}\n\n.placeholder-list-regular {\n\tanimation: pulse 2s;\n\tanimation-iteration-count: infinite;\n\tanimation-timing-function: linear;\n}\n\n.placeholder-list-reverse {\n\tanimation: pulse-reverse 2s;\n\tanimation-iteration-count: infinite;\n\tanimation-timing-function: linear;\n}\n\n.placeholder-gradient {\n\tposition: fixed;\n\theight: 0;\n\twidth: 0;\n\tz-index: -1;\n}\n\n.conversation-placeholder,\n.message-placeholder {\n\n\t&-icon {\n\t\twidth: $clickable-area;\n\t\theight: $clickable-area;\n\t\tcx: calc(#{$clickable-area} / 2);\n\t\tcy: calc(#{$clickable-area} / 2);\n\t\tr: calc(#{$clickable-area} / 2);\n\t}\n}\n\n.conversation-placeholder {\n\twidth: calc(100% - 2 * #{$margin});\n\theight: $clickable-area;\n\tmargin: $margin;\n\n\t&-line-one,\n\t&-line-two {\n\t\twidth: calc(100% - #{$margin + $clickable-area});\n\t\tposition: relative;\n\t\theight: 1em;\n\t\tx: $m